-- PixelRP: the Exterior Modern set, in Builders > Customs.
--
-- 33 exterior pieces - blocks, fences, hedges, half walls, paving and
-- windows - hung under the EXISTING Customs category rather than making a new
-- top-level one, the same way Bsstonino is. Generated by
-- docker/nitro/import-pack-tree.py.
--
-- The pack arrived already converted except for Whitesparring.swf, which went
-- through nitro-converter (yarn start:convert-swf) before being folded in with
-- the rest.
--
-- The rendering half is the .nitro bundles, the icons and the FurnitureData
-- entries under nitro/overrides/; the rows below are inert without them.
--
-- Everything is free - the catalog has been since 90_FreeCatalog.
--
-- Idempotent: fixed id ranges, cleared before insert. The sets under Customs are
-- renumbered alphabetically at the end, which lands the same way every run.

SET @builders := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1),
    912362);
SET @customs := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `id` = 944000 LIMIT 1),
    (SELECT `id` FROM `catalog_pages` WHERE `caption` = 'Customs' AND `parent_id` = @builders
        ORDER BY `id` LIMIT 1));

DELETE FROM `catalog_items` WHERE `item_id` BETWEEN 109900 AND 109932;
DELETE FROM `catalog_pages` WHERE `id` BETWEEN 947000 AND 947999;
DELETE FROM `furniture` WHERE `id` BETWEEN 109900 AND 109932;

     `page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
VALUES
    (947000, @customs, 'Exterior Modern', 193, 2, 0, 1, '', 'default_3x3', '', '', b'1', b'1');

-- Furniture. id == sprite_id, the convention every custom line here follows;
-- interaction_modes_count is the bundle's own animation count.


SET @n := 0;
UPDATE `catalog_pages` SET `order_num` = (@n := @n + 1)
    WHERE `parent_id` = @customs
    ORDER BY `caption`;

-- ---------------------------------------------------------------------------
-- Hand-added after the generator ran, and NOT something import-pack-tree.py
-- will reproduce: re-running the import would emit the rows above without this
-- block, so it lives here as an UPDATE keyed by name rather than as edits to
-- the INSERT.
--
-- The six ground pieces come out of their bundles declaring z = 1.0 and no
-- walkability, which is what the pack really says - Habbo furni routinely
-- declares 1.0 and leaves standing to the furnidata flag the importer cannot
-- see. Imported faithfully, a paved patio is six blocking tiles a builder
-- cannot stand on, which is not what anybody laying paving means.
--
-- So they get the Function tool's own 'rug' preset: walkable, stackable, flat.
-- Named individually rather than matched on LIKE '%floor%' - 'archi_23_door_01'
-- is not a floor, and a pattern that catches it would be a silent trap.
UPDATE `furniture`
    SET `is_walkable` = '1', `stack_height` = 0, `can_stack` = '1'
    WHERE `item_name` IN (
        'archi_23_floor_01',
        'archi_23_floor_tile_01',
        'archi_23_grass_patch_floor_01',
        'archi_23_grass_patch_tile_01',
        'archi_23_pebbles_floor_01',
        'archi_23_pebbles_tile_01');

-- Should read six rows, all walkable at height 0.
SELECT `item_name`, `is_walkable`, `stack_height`, `can_stack`
    FROM `furniture`
    WHERE `item_name` LIKE 'archi\_23\_%'
      AND (`is_walkable` = '1' OR `stack_height` = 0)
    ORDER BY `item_name`;
